    for event in events:
        seen = {part.get('personId') for part in event['participants']}
        for pid,role in more_cast.get(event['id'],[]):
            if pid not in seen:
                event['participants'].append(dict(personId=pid,role=role)); seen.add(pid)
                event['tags'].append(by_person[pid]['name'])
    def edge(a,b,summary,ids,kind='context'):
        relations.append(dict(id=f'{a}--{b}',**{'from':a,'to':b},type=kind,summary=summary,
                              interpretation=True,refs=refs(ids)))
    edge('changan-counterattack','welcome-emperor','长安争权和东归构成196年迎帝都许之前的实际处境。','v006-b0013 v006-b0014 v001-b0031')
    edge('sun-jian-xiangyang','sun-ce-jiangdong','孙坚死后部众归袁术，孙策后来取得旧部再经营江东。','v046-b0009 v046-b0013')
